'use strict';
/* Deterministic editorial recommendation engine — no network, no tracking, no prices invented. */
(function(scope){
 const tierNames={essential:'Essentielle',signature:'Signature',prestige:'Prestige'};
 const movementNames={quartz:'Quartz',automatic:'Automatique','eco-drive':'Solaire'};
 const styleNames={sport:'Sport chic',classic:'Élégance classique',minimal:'Épuré',retro:'Vintage',statement:'Audacieux'};
 const sizeNames={compact:'Boîtier jusqu’à 38 mm',medium:'Boîtier de 38,1 à 40 mm'};
 const diameterMm=p=>{
  // This value is set only for explicitly stated round-case diameters.
  if(Object.hasOwn(p||{},'diameterMm'))return Number.isFinite(p.diameterMm)?p.diameterMm:null;
  const raw=p?.specs?.diameter;
  if(typeof raw!=='string')return null;
  const match=/^(\d{1,2})(?:[,.](\d{1,2}))?\s*mm$/i.exec(raw.trim());
  if(!match)return null;
  const n=Number(match[1]+'.'+(match[2]||'0'));
  return Number.isFinite(n)&&n>0&&n<=65?n:null;
 };
 const isSizeMatch=(diameter,size)=>diameter!==null&&(size==='compact'?diameter<=38:size==='medium'?diameter>38&&diameter<=40:false);
 const allowed={tier:new Set(['all',...Object.keys(tierNames)]),movement:new Set(['all',...Object.keys(movementNames)]),style:new Set(['all',...Object.keys(styleNames)]),size:new Set(['all',...Object.keys(sizeNames)])};
 function choices(input){
  const v=input&&typeof input==='object'?input:{};
  return {tier:allowed.tier.has(v.tier)?v.tier:'all',style:allowed.style.has(v.style)?v.style:'all',movement:allowed.movement.has(v.movement)?v.movement:'all',size:allowed.size.has(v.size)?v.size:'all'};
 }
 function score(p,c,index){
  const details=[];
  let total=0,exact=0,sizeNote='';
  if(c.tier!=='all'){if(p.tier===c.tier){total+=8;exact++;details.push('Gamme '+tierNames[p.tier])}else total-=3}
  if(c.style!=='all'){if(p.style===c.style){total+=7;exact++;details.push(styleNames[p.style])}else if((c.style==='classic'&&p.style==='minimal')||(c.style==='minimal'&&p.style==='classic')){total+=2}else total-=2}
  if(c.movement!=='all'){if(p.movement===c.movement){total+=7;exact++;details.push(movementNames[p.movement])}else total-=3}
  if(c.size!=='all'){
   const n=diameterMm(p);
   if(n===null){total-=2;sizeNote='Diamètre non renseigné : à vérifier chez le fabricant.'}
   else{
    // Normalized supplementary models keep their verified diameter in
    // diameterMm; legacy models still expose specs.diameter. Never assume
    // the legacy specs object exists on a supplementary reference.
    const label=typeof p.specs?.diameter==='string'&&p.specs.diameter.trim()
      ?p.specs.diameter:String(n).replace('.',',')+' mm';
    if(isSizeMatch(n,c.size)){total+=8;exact++;details.push('Diamètre '+label)}
    else{total-=3;sizeNote='Diamètre '+label+' : différent de votre préférence de taille.'}
   }
  }
  const selected=Number(c.tier!=='all')+Number(c.style!=='all')+Number(c.movement!=='all')+Number(c.size!=='all');
  return {product:p,score:total,matched:exact,criteria:selected,details,index,sizeNote};
 }
 function recommend(products,selection,limit=3){
  if(!Array.isArray(products))return [];
  const c=choices(selection),allEmpty=c.tier==='all'&&c.style==='all'&&c.movement==='all'&&c.size==='all';
  const valid=products.filter(p=>p&&typeof p.id==='string'&&Object.hasOwn(tierNames,p.tier)&&Object.hasOwn(styleNames,p.style)&&Object.hasOwn(movementNames,p.movement));
  if(allEmpty){
    const preferred=['casio-mtp-1302','citizen-tsuyosa','tissot-prx-auto'];
    const selected=preferred.map(id=>valid.find(p=>p.id===id)).filter(Boolean);
    const remaining=valid.filter(p=>!selected.includes(p));
    return selected.concat(remaining).slice(0,Math.max(0,Math.min(15,limit))).map((p,i)=>({product:p,score:0,matched:0,criteria:0,details:['Choix de la rédaction'],index:i,sizeNote:''}));
  }
  return valid.map((p,i)=>score(p,c,i)).sort((a,b)=>b.matched-a.matched||b.score-a.score||a.index-b.index).slice(0,Math.max(0,Math.min(15,limit)));
 }
 function coverage(products,selection){
  const c=choices(selection);
  const selected=Number(c.tier!=='all')+Number(c.style!=='all')+Number(c.movement!=='all')+Number(c.size!=='all');
  const valid=Array.isArray(products)?products.filter(p=>p&&typeof p.id==='string'
   &&Object.hasOwn(tierNames,p.tier)&&Object.hasOwn(styleNames,p.style)
   &&Object.hasOwn(movementNames,p.movement)):[];
  if(selected===0)return {selected:0,exact:valid.length,total:valid.length};
  let exact=0;
  for(let i=0;i<valid.length;i++){
   const result=score(valid[i],c,i);
   if(result.matched===selected)exact++;
  }
  return {selected,exact,total:valid.length};
 }
 scope.AtelierAdvisorEngine=Object.freeze({recommend,coverage,choices,tierNames,movementNames,styleNames,sizeNames,diameterMm});
})(globalThis);

/* Atelier Montres — editorial adviser / intentionally independent of external design assets */
.advisor-page{background:#f9f7f2}
.advisor-page .header{position:relative;z-index:10}
.advisor-page a[aria-current=page]{color:#e7cb9c}
.advisor-hero{background:#182b23;color:#f6f2e9;overflow:hidden}
.advisor-hero-layout{display:grid;grid-template-columns:minmax(0,1.06fr) minmax(0,.94fr);align-items:center;gap:25px;min-height:615px}
.advisor-hero-layout>div:first-child{padding:88px 0;position:relative;z-index:2}
.advisor-hero h1{font:400 clamp(59px,7.4vw,108px)/1.02 Georgia,serif;letter-spacing:-.06em;margin:0 0 27px;max-width:650px}
.advisor-hero h1 em{font-style:italic;color:#dec292}
.advisor-lead{max-width:570px;color:#d4ded5;font-size:16px;line-height:1.85;margin:0 0 31px}
.advisor-hero-frame{height:530px;position:relative;display:grid;place-items:center;isolation:isolate}
.advisor-hero-frame:before{content:"";position:absolute;inset:5% 0;background:radial-gradient(circle at 50% 45%,#335640b0,transparent 60%);z-index:-2}
.advisor-hero-ring{position:absolute;width:min(90%,420px);aspect-ratio:1;border:1px solid #dfbf8e45;border-radius:50%;box-shadow:0 0 0 48px #bca7790b;z-index:-1}
.advisor-hero-frame img,.advisor-hero-vector{display:block;max-width:100%;width:min(93%,500px);max-height:92%;object-fit:contain;filter:drop-shadow(18px 27px 30px #080d0999)}
.advisor-hero-vector{height:min(94%,480px);display:grid;place-items:center}.advisor-hero-vector .am-watch-svg{width:100%;height:100%;display:block}
.advisor-hero-caption{position:absolute;bottom:24px;right:0;display:flex;flex-direction:column;align-items:flex-end;gap:3px;text-shadow:0 2px 10px #11251dbb}
.advisor-hero-caption span{color:#d9be92;letter-spacing:.19em;font-size:9px}
.advisor-hero-caption strong{font:400 17px Georgia,serif;letter-spacing:.1em}
.advisor-ticker{background:#eae4d9;border-bottom:1px solid #d9ccba}
.advisor-ticker .wrap{min-height:55px;display:flex;gap:20px;justify-content:space-between;align-items:center;flex-wrap:wrap;padding-top:12px;padding-bottom:12px}
.advisor-ticker span{color:#526354;font:700 10px system-ui,sans-serif;letter-spacing:.14em}
.advisor-custom{padding:98px 0 102px}
.advisor-section-top,.advisor-picks-heading{display:grid;grid-template-columns:1.1fr .9fr;gap:45px;align-items:end;margin-bottom:35px}
.advisor-section-top h2,.advisor-picks-heading h2,.advisor-knowledge h2{font:400 clamp(38px,4.8vw,66px)/1.14 Georgia,serif;letter-spacing:-.04em;margin:0}
.advisor-section-top>p{max-width:470px;color:#657369;font-size:14px;line-height:1.85;margin:0 0 6px}
.advisor-question{border:0;border-top:1px solid #ddd7cc;padding:34px 0 36px;margin:0}
.advisor-question legend{display:flex;gap:16px;align-items:center;float:left;width:100%;font:400 clamp(22px,3vw,33px)/1.2 Georgia,serif;letter-spacing:-.02em;padding:0;margin-bottom:4px;color:#1d3528}
.advisor-question legend:after{content:"";display:block;clear:both}
.advisor-step{display:inline-grid;place-items:center;width:38px;height:38px;border:1px solid #b7a17a;border-radius:50%;font:700 11px system-ui;color:#8f754e;letter-spacing:0;flex-shrink:0}
.advisor-question>p{clear:both;padding-top:6px;margin:0 0 18px;color:#667367;font-size:13px;line-height:1.7}
.advisor-options{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}
.advisor-style{grid-template-columns:repeat(3,minmax(0,1fr))}
.advisor-options label{position:relative;cursor:pointer;min-width:0}
.advisor-options input{position:absolute;top:18px;right:17px;accent-color:#2c5b42;width:18px;height:18px;z-index:1}
.advisor-options label>span{display:flex;flex-direction:column;min-height:100px;padding:20px 39px 20px 19px;border:1px solid #dbd5c9;background:#fffefa;transition:border-color .18s,background .18s,transform .18s}
.advisor-options label>span strong{font:400 clamp(17px,2vw,21px)/1.25 Georgia,serif;letter-spacing:-.015em;color:#203e2c}
.advisor-options label>span small{color:#728076;font-size:11px;line-height:1.6;margin-top:7px}
.advisor-options label:hover>span{border-color:#8d9e8d;background:#f5f9f2}
.advisor-options label:has(input:checked)>span{border-color:#1b543b;background:#e7eee5;box-shadow:inset 0 0 0 1px #1b543b}
.advisor-options input:focus-visible+span{outline:3px solid #c69b59;outline-offset:3px}
.advisor-form-bottom{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:18px;margin-top:10px}
.advisor-reset{font:650 12px system-ui;color:#28523a;background:transparent;border:0;cursor:pointer;padding:13px 0;text-decoration:underline;text-underline-offset:4px}
.advisor-picks{background:#eeeae1;padding:92px 0 100px}
.advisor-picks-heading{margin-bottom:22px}
.advisor-picks-heading>div:last-child{justify-self:end;max-width:440px}
.advisor-criteria{display:inline-flex;padding:7px 12px;border:1px solid #aaa38d;border-radius:99px;color:#456148;text-transform:uppercase;letter-spacing:.1em;font-size:10px;font-weight:700}
.advisor-summary{font-size:13px;line-height:1.8;color:#657064;margin:12px 0 0}
#advisorStatus{font:650 12px system-ui;color:#617367;min-height:25px;margin:0 0 20px}
.advisor-results{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;align-items:stretch}
.advisor-card{background:#fffefa;border:1px solid #ddd5c6;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 13px 32px #1834230a;min-width:0}
.advisor-photo{height:330px;position:relative;display:flex;justify-content:center;align-items:center;padding:23px;background:radial-gradient(circle at 52% 35%,#fffefd,#eae9e1 85%)}
.advisor-photo img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 12px 16px #13271d22)}
.advisor-photo.fallback img{display:none}
.advisor-photo .am-watch-svg{display:block;max-width:92%;max-height:100%;height:100%}
.advisor-photo.fallback .advisor-fallback{position:absolute;bottom:6px;font-size:10px;background:#faf8f0dd;border-radius:4px;padding:5px 8px}
.advisor-fallback{display:none;text-align:center;font-size:13px;color:#5b6d5b;max-width:250px}
.advisor-photo.fallback .advisor-fallback{display:block}
.advisor-rank{position:absolute;top:15px;left:15px;padding:6px 9px;background:#294b36;color:#fff;font-size:10px;letter-spacing:.1em}
.advisor-card-body{padding:25px 23px 24px;display:flex;flex:1;flex-direction:column;gap:0}
.advisor-card-brand{color:#9b774b;font:750 10px system-ui;letter-spacing:.16em;text-transform:uppercase;margin:0 0 8px}
.advisor-card h3{font:400 clamp(22px,2.7vw,31px)/1.12 Georgia,serif;letter-spacing:-.025em;margin:0 0 10px;overflow-wrap:anywhere;color:#193627}
.advisor-card-description{color:#667467;font-size:13px;line-height:1.8;margin:0 0 18px;flex:1}
.advisor-match{margin:0 0 18px;padding:14px;background:#f0f3ed;border-left:2px solid #859a7e;min-height:92px}
.advisor-match-label{font:700 10px system-ui;letter-spacing:.1em;text-transform:uppercase;color:#42634a;display:block;margin-bottom:5px}
.advisor-match p{font-size:12px;line-height:1.65;color:#526653;margin:0}
.advisor-card-actions{display:grid;grid-template-columns:1fr;gap:8px}
.advisor-card-actions a{display:flex;align-items:center;justify-content:center;min-height:45px;padding:11px;text-align:center;text-decoration:none;font:700 11px system-ui;letter-spacing:.04em}
.advisor-card-actions .primary{background:#203d2d;color:#fff}
.advisor-card-actions .secondary{color:#244e36;border:1px solid #c9d2c8}
.advisor-explore{border-top:1px solid #cfc6b5;margin-top:42px;padding-top:29px;display:flex;gap:30px;justify-content:space-between;align-items:center}
.advisor-explore>div{display:flex;flex-direction:column;gap:6px}
.advisor-explore strong{font:400 21px Georgia,serif}
.advisor-explore span{font-size:12px;color:#667364}
.advisor-explore>a{flex-shrink:0;color:#1e4d32;text-decoration:none;font:700 12px system-ui;border-bottom:1px solid #6c876c;padding-bottom:7px}
.advisor-knowledge{background:#203b2b;color:#f5f0e6;padding:87px 0 100px}
.advisor-knowledge h2{color:#fff}
.advisor-knowledge-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin-top:36px;gap:18px}
.advisor-knowledge article{border-top:1px solid #d4bb8655;padding:24px 22px 0 0}
.advisor-knowledge article>span{color:#d8bc85;font:700 12px system-ui;letter-spacing:.2em}
.advisor-knowledge h3{font:400 30px Georgia,serif;margin:16px 0}
.advisor-knowledge article p{color:#c4d1c5;font-size:13px;line-height:1.85;margin:0}
.advisor-error{padding:30px;background:#f5e6d9;color:#613c28}
@media(max-width:1050px){.advisor-options{grid-template-columns:repeat(2,minmax(0,1fr))}.advisor-style{grid-template-columns:repeat(3,minmax(0,1fr))}.advisor-photo{height:275px}.advisor-card-body{padding:21px 17px}}
@media(max-width:760px){.advisor-hero-layout{grid-template-columns:1fr;gap:0}.advisor-hero-layout>div:first-child{padding:66px 0 10px}.advisor-hero-frame{height:390px}.advisor-hero-frame img{width:min(80vw,370px);max-height:360px}.advisor-hero-caption{right:0;bottom:4px}.advisor-hero h1{font-size:clamp(57px,11vw,85px)}.advisor-section-top,.advisor-picks-heading{grid-template-columns:1fr;gap:12px}.advisor-picks-heading>div:last-child{justify-self:start}.advisor-results{grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.advisor-photo{height:240px}.advisor-knowledge-grid{grid-template-columns:1fr}.advisor-knowledge article{padding-bottom:12px}.advisor-custom,.advisor-picks,.advisor-knowledge{padding:68px 0}.advisor-explore{align-items:flex-start;flex-direction:column;gap:19px}}
@media(max-width:560px){.advisor-ticker .wrap{gap:9px}.advisor-ticker span{font-size:9px}.advisor-options,.advisor-style{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.advisor-options label>span{min-height:108px;padding:18px 29px 14px 13px}.advisor-options input{top:17px;right:9px;width:16px;height:16px}.advisor-options label>span strong{font-size:17px}.advisor-hero-frame{height:345px}.advisor-hero h1{font-size:clamp(53px,11vw,69px)}.advisor-results{grid-template-columns:1fr}.advisor-photo{height:305px}.advisor-card h3{font-size:27px}.advisor-card-body{padding:24px}.advisor-match{min-height:0}.advisor-form-bottom .button{width:100%}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.advisor-options label>span{transition:none}}

/* Move naturally from personalized recommendations to a source-backed comparison. */
.advisor-compare-next{display:flex;align-items:center;flex-wrap:wrap;gap:12px 22px;margin:22px 0 0}
.advisor-compare-next .button{min-height:48px;display:inline-flex;align-items:center;text-align:center;justify-content:center}
.advisor-compare-next .button[hidden]{display:none}
.advisor-compare-next p{font-size:13px;color:#647466;margin:0;line-height:1.65;max-width:430px}
@media(max-width:560px){.advisor-compare-next{flex-direction:column;align-items:stretch}.advisor-compare-next .button{width:100%}}
/* Fourth criterion: case size is documented, never inferred from wrist size. */
.advisor-size{grid-template-columns:repeat(3,minmax(0,1fr))}
.advisor-size-question .advisor-size-hint{font-size:13px;line-height:1.7;color:#617365;margin:18px 0 3px}
.advisor-size-hint a{color:#23523a;font-weight:700;text-underline-offset:3px}
.advisor-match .advisor-size-warning{font-size:12px;line-height:1.55;color:#704f23;background:#fff6e5;padding:8px 10px;border-left:2px solid #c49b58;margin:8px 0 0}
@media(max-width:760px){.advisor-size{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:560px){.advisor-size{grid-template-columns:1fr}.advisor-size label>span{min-height:72px;padding-top:14px;padding-bottom:10px}.advisor-size .advisor-size-hint{font-size:12px}}

'use strict';
/* One validated 52-watch public source. No prices, user tracking or back end. */
(() => {
 const engine=globalThis.AtelierAdvisorEngine;
 const form=document.getElementById('advisorForm'),results=document.getElementById('advisorResults'),status=document.getElementById('advisorStatus');
 const summary=document.getElementById('advisorSummary'),criteria=document.getElementById('advisorCriteria'),error=document.getElementById('advisorError'),reset=document.getElementById('advisorReset');
 if(!engine||!form||!results||!status||!summary||!criteria||!error||!reset)return;
 const node=(tag,cls,txt)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(txt!==undefined)e.textContent=txt;return e};
 const read=()=>engine.choices(Object.fromEntries(new FormData(form).entries()));
 let catalogue=[];
 function photo(p,rank){
   const wrap=node('div','advisor-photo'),img=node('img');
   const missing=node('p','advisor-fallback','Photographie non disponible ici ; consultez la fiche du vendeur.');
   const chip=node('span','advisor-rank',String(rank+1).padStart(2,'0')+' / 03');
   const photoUrl=p.photoUrl;
   const safe=typeof photoUrl==='string'
     &&new RegExp('^\\./assets/(?:watches|watches-popular)/'+p.id+'\\.webp$').test(photoUrl);
   img.alt='Photographie du modèle '+p.brand+' '+p.model;
   img.width=540;img.height=540;img.loading='lazy';img.decoding='async';
   img.onerror=()=>{
     img.remove();wrap.classList.add('fallback');
     // A stylised stand-in must never be described as a real model photo.
     if(p.kind==='core')window.AtelierWatch?.render(wrap,p);
   };
   wrap.append(img,missing,chip);
   if(safe)img.src=photoUrl;
   else{img.remove();wrap.classList.add('fallback');if(p.kind==='core')window.AtelierWatch?.render(wrap,p)}
   return wrap;
 }
 function card(entry,i){
   const p=entry.product;
   const item=node('article','advisor-card'),body=node('div','advisor-card-body');
   const title=node('h3','',p.model);
   const brand=node('p','advisor-card-brand',p.brand.toUpperCase());
   const story=node('p','advisor-card-description',p.lead||p.description);
   const match=node('div','advisor-match');
   const allMatched=entry.criteria>0&&entry.matched===entry.criteria;
   const matchLabel=entry.criteria===0?'POINT DE DÉPART':allMatched?'CORRESPOND À VOS CRITÈRES':entry.matched>0?'UNE AUTRE PISTE':'À DÉCOUVRIR';
   const matchText=entry.criteria===0?'Un modèle représentatif de sa gamme, sélectionné par la rédaction.':(entry.details.length?entry.details.join(' · '):'Un style différent, à explorer si vous souhaitez élargir vos critères.');
   match.append(node('span','advisor-match-label',matchLabel),node('p','',matchText));
   if(entry.sizeNote)match.append(node('p','advisor-size-warning',entry.sizeNote));
   const actions=node('div','advisor-card-actions');
   const detail=node('a','primary','Voir la fiche complète ↗');
   detail.href=p.detailUrl;
   const official=node('a','secondary','Voir chez '+p.brand+' ↗');
   official.href=p.officialUrl;official.target='_blank';official.rel='noopener noreferrer nofollow';
   actions.append(detail,official);
   body.append(brand,title,story,match,actions);
   item.append(photo(p,i),body);
   return item;
 }
 function updateAddress(c){
   try{
     const query=new URLSearchParams();
     for(const key of ['tier','style','movement','size'])if(c[key]!=='all')query.set(key,c[key]);
     const next=location.pathname+(query.size?'?'+query.toString():'')+location.hash;
     history.replaceState(null,'',next);
   }catch(_){}
 }
 function render(){
   const choices=read(),recommendations=engine.recommend(catalogue,choices,3);
   const coverage=engine.coverage(catalogue,choices);
   const active=coverage.selected;
   const matches=recommendations.filter(x=>x.criteria>0&&x.matched===x.criteria).length;
   results.replaceChildren(...recommendations.map(card));
   const compareLink=document.getElementById('advisorCompare');
   if(compareLink){
     const ids=recommendations.map(item=>item.product?.id)
       .filter(id=>typeof id==='string'&&/^[a-z0-9-]{4,64}$/.test(id));
     compareLink.hidden=ids.length<2;
     if(ids.length>=2){
       // Preserve every explicit preference in the buyer's compare link.
       // Dedicated pref* keys must not apply a catalogue listing filter,
       // which could hide an alternative watch from the decision.
       const prefs=['tier','style','movement','size'].filter(key=>choices[key]!=='all')
         .map(key=>'&pref'+key[0].toUpperCase()+key.slice(1)+'='+encodeURIComponent(choices[key]))
         .join('');
       compareLink.href='./montres/toutes-les-montres.html?compare='+
         ids.map(encodeURIComponent).join(',')+prefs+'#comparer';
     }
   }
   status.textContent=recommendations.length+' montre'+(recommendations.length>1?'s':'')+' à explorer parmi '+catalogue.length;
   criteria.textContent=active?active+' préférence'+(active>1?'s':'')+' retenue'+(active>1?'s':''):'Sélection de départ';
   summary.textContent=!active
     ?'Notre sélection de départ, issue de plusieurs gammes.'
     :coverage.exact===0
