/* Recommendation clarity: an empty exact-match set is a useful editorial
 * outcome, not a failed request or an invitation to invent product details. */
.advisor-page .advisor-summary[data-match-state="none"]{
  background:#f5e9d6;color:#624520;border-left:4px solid #a36d31;
  border-radius:0 8px 8px 0;padding:13px 16px;line-height:1.65
}
.advisor-page .advisor-summary[data-match-state="exact"]{
  background:#e7efe7;color:#244c3c;border-left:4px solid #48765c;
  border-radius:0 8px 8px 0;padding:13px 16px;line-height:1.65
}
@media(max-width:620px){
 .advisor-page .advisor-summary[data-match-state]{font-size:13px;padding:12px 14px}
}

.am-extra-factual-scroll{max-width:100%;overflow-x:auto;overscroll-behavior-x:contain;border:1px solid #cad7cc;border-radius:9px;margin:22px 0;background:#fff;scrollbar-width:thin}
.am-extra-factual-scroll:focus-visible{outline:3px solid #a87b34;outline-offset:3px}
.am-extra-factual-table{width:100%;min-width:660px;border-collapse:separate;border-spacing:0;text-align:left;color:#203e2d;font:400 13px/1.55 system-ui,sans-serif}
.am-extra-factual-table caption{caption-side:top;text-align:left;padding:15px 16px;font-weight:750;font-size:15px;color:#203e2d}
.am-extra-factual-table th,.am-extra-factual-table td{padding:13px 12px;vertical-align:top;border-top:1px solid #dfe8de;min-width:140px;overflow-wrap:anywhere}
.am-extra-factual-table thead th{background:#edf3eb;font-weight:750}
.am-extra-factual-table tbody th{background:#f6f7f2;min-width:130px;font-weight:750}
.am-extra-factual-table thead th:first-child{min-width:130px}
.am-extra-factual-table thead th:nth-child(2){background:#dbe9dc}
.am-extra-factual-table tbody td:first-of-type{background:#f0f6ec;font-weight:650}
.am-extra-factual-table a{color:#195d38;text-decoration:underline;text-underline-offset:3px}
