.am-pick-compact .am-pick-visual{--visual-bg:#674558;--visual-light:#f4dae0;--visual-ornament:#e2a6bd}
.am-pick-dress .am-pick-visual{--visual-bg:#504838;--visual-light:#f8e9b6;--visual-ornament:#e4d4a7}
.am-pick-steel .am-pick-visual{--visual-bg:#2d4555;--visual-light:#dce7f0;--visual-ornament:#b5d1d5}
.am-pick-visual::before{content:'';position:absolute;top:16%;right:6%;width:145px;max-width:48%;aspect-ratio:1;border:9px solid var(--visual-ornament);border-radius:50%;opacity:.16;transform:rotate(-25deg);box-shadow:0 0 0 18px #ffffff20,0 0 0 31px #ffffff13;pointer-events:none;z-index:-1}
