.am-pick-visual-name{margin-top:auto;color:var(--visual-light);font:750 13px/1.35 system-ui,sans-serif;letter-spacing:.11em;text-transform:uppercase;overflow-wrap:anywhere}
.am-pick-visual-ref{color:#fff;font:400 clamp(24px,2.4vw,34px)/1.17 Georgia,serif;letter-spacing:-.015em;overflow-wrap:anywhere}
.am-pick-visual-caption{color:#ede9df;font:400 11px/1.5 system-ui,sans-serif;opacity:.9}
.am-pick-content{padding:22px;display:flex;flex:1;flex-direction:column;align-items:stretch;gap:11px}
.am-pick-kicker{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:7px;margin:0;color:#6b5536;font:750 11px/1.4 system-ui,sans-serif;text-transform:uppercase;letter-spacing:.035em}
