.am-extra-local-tools{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));
  gap:9px;margin:14px 0 0;padding:13px;
  border:1px solid #d7dfd2;border-radius:10px;background:#f3f6f0}
.am-extra-local-tools button{display:inline-flex;align-items:center;justify-content:center;
  min-width:0;min-height:48px;padding:10px 12px;
  border:1px solid #789482;border-radius:7px;background:#fffefa;color:#214b33;
  font:750 13px/1.5 system-ui,sans-serif;text-align:center;cursor:pointer}
.am-extra-local-tools button:hover{background:#e2eee1}
.am-extra-local-tools .am-extra-favorite[aria-pressed=true]{
  border-color:#28513a;background:#28513a;color:#fff}
.am-extra-local-tools .am-extra-favorite[aria-pressed=true]:hover{
  background:#1e412e}
.am-extra-saved-link{grid-column:1/-1;justify-self:center;
  color:#28513a;text-underline-offset:4px;font:650 12px/1.5 system-ui,sans-serif}
.am-extra-action-status{grid-column:1/-1;margin:0;
  font:650 12px/1.6 system-ui,sans-serif;color:#315b40}
.am-extra-action-status:empty{display:none}
.am-extra-copy-link{grid-column:1/-1;min-width:0;width:100%;box-sizing:border-box;
  padding:10px;border:1px solid #819b87;border-radius:6px;color:#274532;
  background:#fff;font:500 12px/1.5 system-ui,sans-serif}
.am-extra-local-tools button:focus-visible,.am-extra-local-tools a:focus-visible,
.am-extra-copy-link:focus-visible{outline:3px solid #b78b46;outline-offset:3px}
@media(max-width:540px){
  .am-extra-local-tools{grid-template-columns:1fr}
  .am-extra-saved-link,.am-extra-action-status,.am-extra-copy-link{grid-column:1}
}
@media(prefers-reduced-motion:reduce){
  .am-extra-local-tools button{transition:none!important}
}


/* AM-05: two distinct proof paths, not a popularity or stock ranking. */
.am-focus-jump{display:flex;flex-wrap:wrap;gap:11px;margin:0 0 26px}
.am-focus-jump a{display:inline-flex;align-items:center;justify-content:center;
  min-height:46px;padding:10px 17px;border:1px solid #8eaa96;border-radius:6px;
  color:#214933;background:#f1f6ee;text-align:center;text-decoration:none;
  font:750 12px/1.45 system-ui,sans-serif}
.am-focus-jump a:hover{background:#e4eee1}
.am-focus-jump a:focus-visible{outline:3px solid #ba9150;outline-offset:3px}
.am-focus-group{scroll-margin-top:95px;margin:0 0 32px;padding:22px;
  border:1px solid #d7ddcd;border-radius:9px;background:#f5f7f1}
.am-focus-exact{border-color:#b9cbb8;background:#eef3ec}
.am-focus-source{background:#f7f4ed;border-color:#ded4c2}
.am-focus-group-heading{max-width:900px;margin:0 0 20px}
.am-focus-group-heading>p:first-child{font:800 11px/1.5 system-ui,sans-serif;
  letter-spacing:.12em;text-transform:uppercase;color:#6d704d;margin:0 0 5px}
.am-focus-group-heading h3{font:400 clamp(24px,3.3vw,36px)/1.24 Georgia,serif;
  color:#224333;letter-spacing:-.02em;margin:7px 0 12px}
.am-focus-group-heading>p:last-child{max-width:80ch;color:#4a6151;
  font:400 14px/1.75 system-ui,sans-serif;margin:0}
.am-focus-item[data-evidence="documented-asin"]{border-top:3px solid #64876d}
.am-focus-item[data-evidence="manufacturer-source"],
.am-focus-item[data-evidence="partner-source"]{border-top:3px solid #a89167}
.am-focus-proof-label{align-self:flex-start;padding:5px 10px!important;
  border-radius:4px;background:#eaf0e7;color:#285139!important;
  font:750 11px/1.45 system-ui,sans-serif!important}
.am-focus-item[data-evidence="manufacturer-source"] .am-focus-proof-label,
.am-focus-item[data-evidence="partner-source"] .am-focus-proof-label{
  background:#f2ebdd;color:#72552f!important}
@media(max-width:620px){
  .am-focus-jump{display:grid;grid-template-columns:1fr;gap:8px}
  .am-focus-group{padding:12px;margin-bottom:25px}
  .am-focus-group-heading{padding:4px 4px 0}
  .am-focus-group-heading h3{font-size:27px}
}

/* Real-photo product sheets: pale atelier stage, full unoccluded packshot,
   and a distinct factual caption. Unphotographed editorial pages deliberately
   keep their existing graphic composition. No remote assets or new fonts. */
.am-extra-art.am-extra-art-with-photo{
  display:flex;flex-direction:column;justify-content:flex-start;gap:0;
  min-height:0;padding:clamp(11px,1.45vw,20px);overflow:hidden;
  border:1px solid #d5c7ae;border-radius:8px;
  color:#203d2c;background:linear-gradient(152deg,#fffdf6,#f4f0e7 65%,#ebe6dc);
  box-shadow:0 16px 45px rgba(25,44,31,.11)
}
.am-extra-art-with-photo::before,
.am-extra-art-with-photo::after{content:none;display:none}
.am-extra-photo-stage{
  position:relative;isolation:isolate;display:grid;place-items:center;
  box-sizing:border-box;min-width:0;width:100%;
  height:clamp(320px,35vw,505px);
  border:1px solid #e4e0d4;border-radius:5px;overflow:hidden;
  background:radial-gradient(ellipse at 47% 38%,#fffdfa 0%,#f0eee8 63%,#e2dfd7 100%)
}
.am-extra-photo-stage::before{
  content:"";position:absolute;inset:12px;pointer-events:none;
  border:1px solid rgba(255,255,255,.72);z-index:0
}
.am-extra-art-with-photo .am-extra-photo-stage .am-extra-licensed-photo{
  position:relative;inset:auto;top:auto;right:auto;
  display:block;box-sizing:border-box;width:100%;height:100%;
  max-width:100%;max-height:100%;object-fit:contain;
  padding:clamp(17px,3vw,35px);z-index:1;mix-blend-mode:multiply;
  filter:drop-shadow(0 16px 15px rgba(35,45,34,.19));
  transition:transform .25s ease
}
.am-extra-photo-meta{
  display:flex;flex-direction:column;align-items:flex-start;gap:6px;
  min-width:0;padding:clamp(17px,2vw,24px) clamp(9px,2vw,17px) 10px
}
.am-extra-art-with-photo .am-extra-photo-meta .am-extra-art-kicker{
  margin:0 0 3px;padding:0;border:0;border-radius:0;
  background:transparent;color:#816842;
  font:750 10px/1.5 system-ui,sans-serif;letter-spacing:.10em;
  text-transform:uppercase
}
.am-extra-art-with-photo .am-extra-photo-meta .am-extra-art-brand{
  color:#365e46;text-shadow:none;
  font:750 11px/1.5 system-ui,sans-serif;letter-spacing:.16em
}
.am-extra-art-with-photo .am-extra-photo-meta .am-extra-art-model{
  margin:0 0 2px;max-width:100%;overflow-wrap:anywhere;
  color:#203a2b;text-shadow:none;
  font:400 clamp(26px,2.8vw,37px)/1.12 Georgia,serif;letter-spacing:-.025em
}
.am-extra-art-with-photo .am-extra-photo-meta .am-extra-art-label{
  color:#59695b;text-shadow:none;
  font:500 11px/1.55 system-ui,sans-serif;overflow-wrap:anywhere
}
.am-extra-art-with-photo .am-extra-photo-stage .am-extra-zoom{
  position:absolute;top:auto;bottom:13px;right:13px;z-index:3;
  display:inline-flex;align-items:center;justify-content:center;
  min-width:44px;min-height:44px;max-width:calc(100% - 26px);
  padding:10px 14px;box-shadow:0 6px 22px rgba(25,47,31,.15);
  background:rgba(255,253,247,.97);color:#234632;border:1px solid #b5a080
}
.am-extra-art-with-photo .am-extra-photo-stage .am-extra-zoom[hidden]{display:none!important}
.am-extra-art-with-photo .am-extra-photo-stage .am-extra-zoom:hover{
  background:#224b34;color:#fff
}
.am-extra-art-with-photo .am-extra-photo-stage .am-extra-zoom:focus-visible{
  outline:3px solid #b58337;outline-offset:3px
}
@media(hover:hover) and (pointer:fine){
  .am-extra-art-with-photo .am-extra-photo-stage:hover .am-extra-licensed-photo{transform:scale(1.03)}
}
@media(max-width:900px){
  .am-extra-photo-stage{height:clamp(320px,52vw,480px)}
}
@media(max-width:760px){
  .am-extra-art.am-extra-art-with-photo{padding:11px;min-height:0}
  .am-extra-photo-stage{height:clamp(290px,85vw,430px)}
  .am-extra-photo-meta{padding:16px 13px 10px;gap:5px}
  .am-extra-art-with-photo .am-extra-photo-meta .am-extra-art-model{font-size:clamp(26px,6.2vw,34px)}
}
@media(max-width:520px){
  .am-extra-art.am-extra-art-with-photo{padding:9px;min-height:0}
  .am-extra-photo-stage{height:clamp(265px,88vw,365px)}
  .am-extra-photo-stage::before{inset:7px}
  .am-extra-art-with-photo .am-extra-photo-stage .am-extra-licensed-photo{padding:15px}
  .am-extra-art-with-photo .am-extra-photo-stage .am-extra-zoom{
    bottom:10px;right:10px;padding:9px 11px;font-size:12px
  }
  .am-extra-photo-meta{padding:14px 11px 9px}
}
@media(prefers-reduced-motion:reduce){
  .am-extra-art-with-photo .am-extra-photo-stage .am-extra-licensed-photo{
    transform:none!important;transition:none!important
  }
}

/* Atelier Montres | public, customer-facing premium showroom.
   Lightweight CSS only: product photography already hosted locally; no new font
   services, fake stock indicators, speculative prices or payment bypass. */
:root{--show-ink:#1a2923;--show-olive:#293c31;--show-bronze:#aa8451;--show-paper:#fbf8f2;--show-stone:#eee9df;--show-line:#ded4c6}
body.am-showroom-home{background:var(--show-paper)}
.am-showroom-home .header{background:#15231e;border-bottom-color:rgba(237,213,170,.19)}
.am-showroom-home .header-inner{max-width:1360px}
.am-showroom-home .brand{font:400 clamp(22px,2.4vw,30px)/1.1 Georgia,serif;letter-spacing:.015em}
.am-showroom-home .home-nav a{font-weight:680;letter-spacing:.055em;transition:color .18s ease}
.am-showroom-home .home-nav-buy{border:1px solid #c4a77a;padding:12px 18px;color:#ffedd0;border-radius:2px}
.am-showroom-home .home-nav-buy:hover{background:#e5cdab;color:#1d3024}
.am-showroom-home .home-hero{background:linear-gradient(122deg,#152520 12%,#273c30 65%,#1b3027);isolation:isolate}
.am-showroom-home .home-hero::before{background:radial-gradient(circle at 72% 46%,rgba(225,195,148,.17),transparent 48%),linear-gradient(0deg,rgba(12,24,18,.3),transparent 40%)}
.am-showroom-home .home-hero-grid{max-width:1360px;min-height:650px;grid-template-columns:1fr minmax(0,.86fr);gap:clamp(45px,7vw,105px);padding-block:68px 80px}
.am-showroom-home .home-hero-copy::before{content:"ATELIER / COLLECTION 2026";display:block;font-size:11px;letter-spacing:.22em;color:#e1cfb1;border-left:2px solid #c7a36a;padding-left:14px;margin-bottom:26px}
.am-showroom-home .home-hero h1{font:400 clamp(60px,6.6vw,110px)/.98 Georgia,"Times New Roman",serif;letter-spacing:-.065em;max-width:680px;text-wrap:balance}
.am-showroom-home .home-hero h1 em{color:#ebcb98;font-weight:400}
.am-showroom-home .home-hero .hero-lead{max-width:540px;color:#e1e8dd;font-size:clamp(16px,1.65vw,20px);line-height:1.75}
.am-showroom-home .home-actions{gap:17px}
.am-showroom-home .home-actions .button{background:#e2bd86;color:#1d2f24;border-color:#e2bd86;min-height:55px;padding-inline:27px;border-radius:3px;box-shadow:0 8px 25px rgba(3,11,5,.16)}
.am-showroom-home .home-actions .button:hover{background:#f4d9ae;border-color:#f4d9ae}
.am-showroom-home .home-text-link{color:#f6eadd}
.am-showroom-home .home-hero-note{max-width:530px;color:#c9d8ce;border-left:1px solid rgba(238,201,150,.55);padding-left:16px;font-size:12px}
.am-showroom-home .home-hero-visual{border:1px solid rgba(253,226,188,.4);border-radius:8px;background:radial-gradient(circle at 45% 38%,#f9f5e9 0,#e6decf 44%,#c0b8a8 100%);box-shadow:0 36px 65px rgba(0,0,0,.28),inset 0 0 0 12px rgba(255,255,255,.12);transform:rotate(1.5deg);transition:transform .22s ease,box-shadow .22s ease}
.am-showroom-home .home-hero-visual:hover{transform:rotate(0) translateY(-4px);box-shadow:0 42px 78px rgba(0,0,0,.34)}
.am-showroom-home .home-hero-visual::before{content:"01 / ÉDITION SIGNATURE";position:absolute;left:19px;top:18px;z-index:2;font-size:10px;letter-spacing:.18em;color:#36503e;font-weight:750}
.am-showroom-home .home-hero-visual img{padding:5%;filter:drop-shadow(0 22px 16px rgba(31,34,25,.12))}
.am-showroom-home .home-hero-visual-caption{background:linear-gradient(0deg,rgba(16,31,23,.98),rgba(22,40,30,.88));padding:22px 24px;font-size:11px;letter-spacing:.07em}
.am-showroom-home .home-promise{background:#f2ece1}
.am-showroom-home .home-promise-items{padding-block:29px;gap:27px}
.am-showroom-home .home-promise-items p{border-color:#b08e5d;padding-left:20px}
.am-showroom-home .home-promise-items strong{font-weight:750;color:#253e2c}
.am-showroom-home .home-promise-items span{font-size:13px;color:#4f6152}
.am-budget-section{scroll-margin-top:25px;padding:clamp(70px,9vw,126px) 0;background:#f9f6ef;border-bottom:1px solid #e5dacb}
.am-budget-heading{display:grid;grid-template-columns:1fr minmax(260px,.7fr);gap:50px;align-items:end;margin-bottom:42px}
.am-budget-heading h2{font-size:clamp(44px,5.4vw,75px);letter-spacing:-.055em;line-height:1.04}
.am-budget-heading h2 em{color:#8f6c44;font-weight:400}
.am-budget-heading>p{font-size:17px;line-height:1.8;color:#526759;margin:0;max-width:520px}
.am-budget-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
.am-budget-card{display:flex;flex-direction:column;background:#fffdf8;color:#22352a;border:1px solid #ded3c3;box-shadow:0 16px 45px rgba(38,46,27,.07);text-decoration:none;min-width:0;border-radius:8px;overflow:hidden;transition:transform .22s ease,box-shadow .22s ease,border-color .22s}
.am-budget-card:hover{transform:translateY(-5px);box-shadow:0 23px 56px rgba(33,42,29,.16);border-color:#b8996a}
.am-budget-card:focus-visible{outline:3px solid #b88644;outline-offset:4px}
.am-budget-art{position:relative;background:radial-gradient(circle at 51% 42%,#f5f3ec 0,#d6d6cc 60%,#b9b7ab 100%);overflow:hidden;aspect-ratio:1.22}
.am-budget-card:nth-child(2) .am-budget-art{background:radial-gradient(circle,#eaf2eb 0,#cad7cd 62%,#a1b2a5 100%)}
.am-budget-card:nth-child(3) .am-budget-art{background:radial-gradient(circle,#e7eaf0 0,#c9d1db 62%,#9aabbd 100%)}
.am-budget-art::after{content:"ATELIER MONTRES";position:absolute;right:16px;bottom:12px;color:#435547;font-size:10px;letter-spacing:.18em;opacity:.6;font-weight:700}
.am-budget-art img{display:block;max-width:100%;width:100%;height:100%;object-fit:contain;padding:5% 13% 7%;filter:drop-shadow(12px 23px 16px rgba(29,35,26,.18));transition:transform .35s ease}
.am-budget-card:hover .am-budget-art img{transform:scale(1.06)}
.am-budget-copy{padding:28px 27px 31px;display:flex;flex-direction:column;gap:12px;flex:1}
.am-budget-kicker{font-size:11px;letter-spacing:.14em;text-transform:uppercase;font-weight:800;color:#78603e}
.am-budget-copy strong{font:400 clamp(28px,2.6vw,37px)/1.12 Georgia,serif;letter-spacing:-.035em;min-height:2.1em}
.am-budget-range{background:#f2e9d9;border:1px solid #e0d3be;padding:8px 12px;width:max-content;max-width:100%;font-size:13px;color:#394e3a;font-weight:750;border-radius:2px}
.am-budget-copy p{color:#546658;font-size:14px;line-height:1.75;margin:0 0 4px}
.am-budget-action{margin-top:auto;color:#1f4d32;font-weight:780;font-size:13px;letter-spacing:.02em;text-decoration:underline;text-underline-offset:5px}
.am-budget-disclaimer{font-size:12px;line-height:1.7;color:#586859;max-width:850px;margin:23px 0 0}
.am-showroom-home .home-products{background:#fffdf9;padding-top:clamp(76px,9vw,125px)}
.am-showroom-home .home-section-head h2{font-size:clamp(38px,4.8vw,66px);letter-spacing:-.046em}
.am-edit-tier{padding:clamp(35px,5vw,65px) 0 32px;border-top:1px solid #d7d2c8;scroll-margin-top:20px}
.am-edit-tier-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:26px}
.am-edit-tier-head>div>p{color:#8b6c46;font-size:12px;letter-spacing:.18em;text-transform:uppercase;font-weight:800;margin:0 0 10px}
.am-edit-tier-head h3{font:400 clamp(29px,3.6vw,47px)/1.12 Georgia,serif;letter-spacing:-.04em;margin:0;color:#24392b}
.am-edit-tier-head>span{color:#58695c;font-size:14px;max-width:330px;text-align:right;line-height:1.6}
.am-showroom-home .home-product-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}
.am-showroom-home .home-product-card{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.91fr);border-radius:6px;box-shadow:0 11px 34px rgba(27,39,27,.06);min-height:285px}
.am-showroom-home .home-product-image{display:flex;justify-content:center;align-items:center;background:radial-gradient(circle at 47% 42%,#f4f3ed 0,#e0e0d7 69%,#d0cfc5 100%)}
.am-showroom-home .home-product-image img{width:100%;height:100%;object-fit:contain;aspect-ratio:1;padding:8%;filter:drop-shadow(10px 15px 13px rgba(32,35,30,.14))}
.am-showroom-home .home-product-body{padding:clamp(18px,2vw,27px);gap:13px;justify-content:center}
.am-showroom-home .home-product-body h4{font:400 clamp(24px,2.4vw,35px)/1.12 Georgia,serif;letter-spacing:-.035em;margin:0;color:#233b2d}
.am-showroom-home .home-product-body p{font-size:14px;line-height:1.7}
.am-showroom-home .home-product-body a:not(.am-direct-card-link){font-weight:750;color:#245237;text-underline-offset:5px}
.am-showroom-home .home-product-body .am-direct-card-link{display:block;padding:12px 13px;background:#234631;color:white;border-radius:3px;font-size:12px;line-height:1.45;text-decoration:none;font-weight:700;margin:10px 0 0}
.am-tier-footnote{font-size:13px;line-height:1.65;color:#687266;margin:17px 0 0}
.am-showroom-home .home-disclosure{max-width:910px;background:#f4f1e9;border-left:3px solid #b49363;padding:17px 22px;margin-top:16px}
.am-order-story{padding:clamp(80px,8vw,125px) 0;background:#1b3026;color:#f9f3e9;position:relative;overflow:hidden}
.am-order-story::before{content:"";position:absolute;width:650px;height:650px;border:1px solid rgba(237,210,175,.14);border-radius:50%;right:-280px;top:-340px;pointer-events:none;box-shadow:0 0 0 80px rgba(237,210,175,.015)}
.am-order-story-intro{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.85fr);gap:40px;align-items:end;position:relative}
.am-order-story .overline{grid-column:1/-1;margin:0}
.am-order-story h2{color:#fff9ee;font-size:clamp(40px,4.8vw,65px);line-height:1.08}
.am-order-story h2 em{color:#debd89}
.am-order-story-intro>p:last-child{font-size:16px;color:#d3ded4;line-height:1.8;margin:0}
.am-order-story-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:53px}
.am-order-story-grid>div{padding:27px 26px 31px;border:1px solid rgba(224,198,155,.33);background:rgba(255,255,255,.045)}
.am-order-story-grid span{font:400 31px Georgia,serif;color:#edc890}
.am-order-story-grid h3{font:400 25px Georgia,serif;margin:16px 0 10px;color:#fffdf8}
.am-order-story-grid p{margin:0;color:#d2e0d4;font-size:14px;line-height:1.75}
.am-order-story-status{background:rgba(232,206,165,.1);border-left:3px solid #dfbd86;margin:30px 0 0;padding:17px 20px;color:#f7e8d4;font-size:13px;line-height:1.75}
.am-order-story-status a{color:#ffe6be;font-weight:750;text-underline-offset:4px}

/* Public buying guide: practical navigation rather than inactive checkout. */
.am-buyer-guide .am-order-story-grid>div{display:flex;flex-direction:column;align-items:flex-start}
.am-buyer-guide .am-order-story-grid h3{margin-bottom:12px}
.am-buyer-guide .am-order-story-grid a{display:inline-flex;align-items:center;min-height:44px;margin-top:auto;padding-top:16px;color:#ffe0a9;font-size:13px;font-weight:750;text-underline-offset:5px;line-height:1.5}
.am-buyer-guide .am-order-story-grid a:hover{color:#fff7e8}
.am-buyer-guide .am-order-story-grid a:focus-visible{outline:3px solid #f2d09a;outline-offset:4px}
@media(hover:none){
  .am-showroom-home .home-hero-visual,.am-showroom-home .home-hero-visual:hover{transform:none}
  .am-budget-card:hover,.am-budget-card:hover .am-budget-art img{transform:none}
  .am-editorial-path:hover,.am-editorial-path:hover .am-editorial-path-photo img{transform:none}
}

.am-showroom-home .home-guidance{background:#eee8dc}
.am-showroom-home .home-method{background:#ebefe8}
.am-showroom-home .home-choice{border-radius:5px;box-shadow:0 8px 22px rgba(35,39,28,.035)}
