.am-editorial-path{display:flex;flex-direction:column;min-width:0;background:#fffdf8;text-decoration:none;color:#203629;border:1px solid #d8d6c8;overflow:hidden;border-radius:5px;box-shadow:0 15px 35px rgba(29,41,29,.065);transition:transform .24s ease,box-shadow .24s ease,border-color .24s ease}
