/* Atelier Montres: indexable editorial pages, no third-party fonts or scripts. */
:root{color-scheme:light;--ink:#183229;--accent:#a08350;--paper:#f8f5ec;--line:#dfd7c8}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
.wrap{width:min(1160px,calc(100% - 40px));margin-inline:auto}a{color:inherit;text-underline-offset:3px}a:focus-visible{outline:3px solid #b18c52;outline-offset:4px}.skip{position:absolute;top:-100px;left:14px;background:white;padding:10px;z-index:10}.skip:focus{top:10px}
.top{background:#172d25;color:#f8f2e5}.nav{min-height:78px;display:flex;align-items:center;justify-content:space-between;gap:20px}.logo{text-decoration:none;font:400 26px/1.2 Georgia,serif;white-space:nowrap}.nav nav{display:flex;gap:24px;flex-wrap:wrap}.nav nav a{font-size:14px;text-decoration:none}.nav nav a:hover{text-decoration:underline}
.crumb{font-size:13px;color:#57695b;padding:24px 0}.watch{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,70px);align-items:center;padding:16px 0 64px}
.photo{min-height:350px;background:#f0ebe0;border:1px solid var(--line);display:grid;place-items:center;overflow:hidden}.photo img{width:100%;height:auto;max-height:560px;aspect-ratio:1;object-fit:contain}
.photo:has(.watch-vector){display:flex;flex-direction:column;justify-content:center;gap:8px;padding:24px}
.watch-vector{width:min(100%,390px);margin:auto;min-height:330px;display:grid;place-items:center}
.watch-vector .am-watch-svg{width:100%;max-height:460px;display:block}
.watch-vector-note{font-size:12px;line-height:1.6;text-align:center;color:#4e5c51;max-width:350px;margin:auto}
@media(max-width:720px){.watch-vector{min-height:260px}.photo:has(.watch-vector){padding:12px}}.eyebrow{display:block;color:#74623d;letter-spacing:.13em;text-transform:uppercase;font-weight:700;font-size:12px}.intro h1,.editorial h1{font:400 clamp(35px,5.5vw,66px)/1.09 Georgia,serif;margin:18px 0}.intro .subtitle{font:italic 24px Georgia,serif;color:#566756}.lead{font-size:18px;line-height:1.85;color:#46584e}.tags{display:flex;flex-wrap:wrap;gap:7px;margin:24px 0}.tags span{padding:7px 12px;background:#ede6d6;font-size:12px;border:1px solid #e0d2b7}.disclosure{font-size:13px;color:#536159;line-height:1.7;border-left:3px solid var(--accent);padding-left:14px}
.primary,.secondary{display:inline-block;text-align:center;text-decoration:none;padding:15px 20px;margin:12px 12px 0 0;min-height:52px;font-weight:650;font-size:14px}.primary{background:#193629;color:#fff}.primary:hover{background:#285142}.secondary{border:1px solid #647765}.secondary:hover{background:#ece7dc}
.content{max-width:900px;padding:20px 0 90px}.content h2{font:400 clamp(26px,3vw,38px)/1.25 Georgia,serif;margin:44px 0 14px}.content p{line-height:1.9;color:#43584b}.content dl{border-top:1px solid var(--line)}.content dl>div{display:grid;grid-template-columns:45% 1fr;padding:14px 8px;border-bottom:1px solid var(--line)}.content dt{font-weight:650}.content dd{margin:0}
.related{list-style:none;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.related li{padding:16px;background:#fffefa;border:1px solid var(--line)}.related a{display:block;font-weight:700}.related span,.related small{font-size:13px;display:block;color:#617063;margin-top:6px}.editorial{max-width:1050px}.editorial>.lead{max-width:800px}footer{background:#172d25;color:#f4ead8;padding:50px 0;font-size:13px}footer strong{font:400 27px Georgia,serif}footer p{max-width:780px;color:#d4d9ce}
.seo-links{padding:72px 0;background:#eee9df;border-top:1px solid #e1d7c8}.seo-links h2{font:400 clamp(32px,4vw,48px) Georgia,serif;margin:15px 0}.seo-links>div>p{max-width:750px}.seo-links ul{list-style:none;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.seo-links li{background:#fffcf7;border:1px solid #e3daca;padding:16px;display:flex;flex-direction:column;gap:6px}.seo-links li a{font-weight:650;color:#203d2c}.seo-links li small{font-size:12px;color:#627063}.seo-links>div>p:last-child{margin-top:26px;font-weight:600}
@media(max-width:720px){.wrap{width:min(100% - 28px,1160px)}.nav{align-items:flex-start;flex-direction:column;padding:17px 0;gap:13px}.nav nav{gap:14px}.nav nav a{font-size:13px}.watch{grid-template-columns:1fr;padding-bottom:32px;gap:16px}.photo{min-height:260px}.photo img{max-height:390px}.related{grid-template-columns:1fr}.seo-links ul{grid-template-columns:repeat(2,minmax(0,1fr))}.content{padding-bottom:56px}.primary,.secondary{margin-right:0;width:100%}}
